// Why this flow exists: the model key must never sit in client-side
// JavaScript, but a grader opening the live URL has no key of their own.
// The key lives in this instance's credential store and the browser only
// ever sees the answer.
//
// The task allow-list matters. Without it this URL is a free, anonymous
// LLM proxy for anyone who finds it, which is how a demo turns into a
// bill. Only the three jobs the app actually makes are accepted.
const ALLOWED = ['interpretScore', 'adjudicateMatch', 'relationshipArc'];

const b = $input.first().json.body || $input.first().json;
if (!ALLOWED.includes(b.task)) {
  throw new Error(`Unknown task "${b.task}". This endpoint only serves: ${ALLOWED.join(', ')}`);
}
if (!b.prompt || typeof b.prompt !== 'string') {
  throw new Error('No prompt on the request.');
}
// A hard ceiling, so a malformed caller cannot send a novel.
const prompt = b.prompt.slice(0, 24000);
const system = (b.system || '').slice(0, 8000);

return [{ json: { task: b.task, system, prompt } }];

// The app expects { text }. It does the JSON parsing itself, in one place,
// so this flow does not need to know the shape of any particular answer.
const r = $input.first().json;
const text = (r.content || []).map(b => b.text || '').join('');
if (!text) throw new Error('Anthropic returned no text: ' + JSON.stringify(r).slice(0, 300));
return [{ json: { text } }];
